 if(t.column"'!==1&&source.split('"'\\n')[t.line-1].slice(0,t.column-1).trim())fail(t,'Definicja musi zaczynać się na początku wiersza.');
 p++;let h=[];while(p<tokens.length&&tokens[p].line===t.line)h.push(tokens[p++]);let name=h.shift();if("'!name||!/''^'"\\p{L}[\\p{L}\\p{N}_]*"'$/u.test(name.v)||aliases[name.v]||defs.has(name.v)||['"'oto','to',...ends].includes(name.v))fail(name||t,'Nieprawidłowa lub powtórzona nazwa procedury.');
